function kimpu_design_dark_css() { return array( '--km-background' => kimpu_design_color( 'dark_background' ), '--km-page-background' => kimpu_design_color( 'dark_background' ), '--km-surface' => kimpu_design_color( 'dark_surface' ), '--km-card' => kimpu_design_color( 'dark_card' ), '--km-section' => kimpu_design_color( 'dark_surface' ), '--km-heading' => kimpu_design_color( 'dark_heading' ), '--km-text' => kimpu_design_color( 'dark_text' ), '--km-muted' => kimpu_design_color( 'dark_muted' ), '--km-border' => kimpu_design_color( 'dark_border' ), '--km-input-background' => kimpu_design_color( 'dark_card' ), '--km-input-border' => kimpu_design_color( 'dark_border' ), '--color-dark' => kimpu_design_color( 'dark_heading' ), '--color-text' => kimpu_design_color( 'dark_text' ), '--color-muted' => kimpu_design_color( 'dark_muted' ), '--color-surface' => kimpu_design_color( 'dark_surface' ), '--color-border' => kimpu_design_color( 'dark_border' ) ); }

function kimpu_design_tokens_css() {
	$css_value = function( $value ) { return str_replace( array( '<', '>', ';', '{', '}' ), '', (string) $value ); };
	$css = ':root{'; foreach ( kimpu_design_css_variables() as $property => $value ) { $css .= $property . ':' . $css_value( $value ) . ';'; } $css .= '}[data-theme="dark"]{'; foreach ( kimpu_design_dark_css() as $property => $value ) { $css .= $property . ':' . $css_value( $value ) . ';'; } $css .= '}@media (prefers-color-scheme:dark){[data-theme="system"]{'; foreach ( kimpu_design_dark_css() as $property => $value ) { $css .= $property . ':' . $css_value( $value ) . ';'; } $css .= '}}';
	if ( ! get_theme_mod( 'kimpu_header_border', false ) ) { $css .= '.site-header{border-bottom:0!important;}'; } if ( ! get_theme_mod( 'kimpu_header_shadow', false ) ) { $css .= '.site-header:not(.is-scrolled){box-shadow:none;}'; } if ( ! get_theme_mod( 'kimpu_footer_border', true ) ) { $css .= '.site-footer{border-top:0!important;}'; } if ( get_theme_mod( 'kimpu_design_reduced_motion', false ) ) { $css .= '*,*:before,*:after{transition-duration:.01ms!important;animation-duration:.01ms!important;scroll-behavior:auto!important;}'; }
	return $css;
}
